import re, pathlib
from collections import Counter
et=Counter(); leg=Counter(); etd={}; legd={}
QUAL=r'(?:[A-Za-z_][A-Za-z0-9_.\']*\.)?'
for p in sorted(pathlib.Path('AlgebraicJacobian').rglob('*.lean')):
    src=p.read_text()
    src=re.sub(r'/-.*?-/', '', src, flags=re.S)
    src=re.sub(r'--[^\n]*', '', src)
    lines=src.split('\n'); blocks=[]; cur=[]
    kw=re.compile(r'^(private |protected |noncomputable |scoped |local |@\[[^\]]*\]\s*)*(theorem|lemma|def|abbrev|instance|class|structure|example)\b')
    for ln in lines:
        if kw.match(ln):
            if cur: blocks.append('\n'.join(cur))
            cur=[ln]
        elif cur: cur.append(ln)
    if cur: blocks.append('\n'.join(cur))
    for b in blocks:
        m=re.search(r':=|\bwhere\b', b)
        sig=b[:m.start()] if m else b
        nm=re.search(r'(?:theorem|lemma|def|abbrev|instance|class|structure)\s+([^\s({\[:]+)', b)
        nm=nm.group(1) if nm else '?'
        if re.search(r'\[\s*'+QUAL+r'HasPicSchemeEt\b', sig): et[str(p)]+=1; etd.setdefault(str(p),[]).append(nm)
        elif re.search(r'\[\s*'+QUAL+r'HasPicScheme\b', sig): leg[str(p)]+=1; legd.setdefault(str(p),[]).append(nm)
print("=== HasPicSchemeEt binders:", sum(et.values()))
for k,v in et.most_common(): print("   ",v,k)
print("=== HasPicScheme (legacy) binders:", sum(leg.values()))
for k,v in leg.most_common(): print("   ",v,k)
print()
print("Jacobian.lean legacy decls:", legd.get('AlgebraicJacobian/Jacobian.lean'))
EOF
